  estimateLipsync(params: Params<T.EstimateLipsyncData> & WithIdempotencyKey): Promise<RaskResponse<T.EstimateLipsyncResponse>> {
    return this.transport.call(OPERATIONS.estimateLipsync, sdk.estimateLipsync, params);
  }
